// mixedAssertItemsZeroOnError asserts Items returns nothing alongside any error.
func mixedAssertItemsZeroOnError(
	tb testing.TB,
	m Mixed,
) {
	tb.Helper()
	ctx, cancel := context.WithCancel(tb.Context())
	cancel()
	got, err := m.Items(ctx)
	if err == nil {
		tb.Skip("Items answered for a cancelled context, so this check has no error to inspect")
	}

	if got != nil {
		tb.Errorf("Items must return nothing alongside an error (err %v)", err)
	}
}

// MixedDefect is a deliberately broken implementation, used as
// evidence that a check can fail. In practice you build one with
// BrokenMixed over the generated test double.
type MixedDefect interface {
	Subject() (MixedSubject, error)
}

// BrokenMixed describes an implementation built to break one
// specific claim, so that a check can be shown to catch it.
//
// Give it a name saying what is wrong, and a constructor. The best
// broken implementation is the generated double wrapping a correct one,
// with a single method overridden — correct everywhere except the one
// place the check is about.
func BrokenMixed[T Mixed](
	name string, build func() T,
) MixedHarness[T] {
	return MixedHarness[T]{
		Name: name, New: build,
	}
}

// MixedChecks is a table of checks you write yourself, for the
// claims that cannot be worked out from the declaration — the ones that
// carry your domain.
//
// They are the same kind of value as the generated checks: they appear
// in the report, they can be dropped by name, and they can say what they
// need from an implementation. There is no second mechanism for them.
//
//	var myChecks = MixedChecks{
//		{Method: "Merge", Name: "my-claim",
//			Claim:    "a sentence stating exactly what this check proves",
//			Run:      myClaimBody,
//			ProvenBy: BrokenMixed("an implementation that breaks it", newBroken)},
//	}
type MixedChecks []MixedCheck

func (c MixedChecks) applyTo(rc *mixedRunConfig) {
	rc.rows = append(rc.rows, c...)
}

// MixedCheck is one check you wrote. The body is a plain named
// function; which field you put it in decides what it is handed.
type MixedCheck struct {
	// Method groups this check under one of your methods, so it is named
	// Merge/<Name> in output and reruns with the rest of that
	// method's checks. Leave it empty for a check that is not about one
	// method in particular.
	Method string

	// Name identifies this check, in output and when dropping it. Keep it
	// stable: it is what a colleague's Without call refers to.
	Name string

	// Claim is one sentence saying exactly what this check proves. It is
	// recorded in the manifest and read out in the report.
	//
	// Write only what the body actually establishes. "a second write
	// leaves the value unchanged" is a promise that something reads the
	// value back; if the body only checks the write returned no error,
	// say that instead. Nothing here can catch a claim that is wider
	// than its check, and a claim nobody verifies is worse than none.
	Claim string

	// Set exactly one.
	//
	// Run is handed one fresh instance, which suits nearly every check.
	// RunWith is handed something that can build instances, for a claim
	// one instance cannot state on its own: build two and compare them,
	// move the clock forward, put one into a failure state.
	//
	// Both are also handed the sample inputs, so a check you write draws
	// from the same values the generated ones do — override an input and
	// your check sees the override too.
	Run     func(tb testing.TB, s Mixed, fx MixedFixture)
	RunWith func(tb testing.TB, sub MixedSubject, fx MixedFixture)

	// Class groups this check in the report's summary. Optional; checks
	// you write are grouped as hand-written by default.
	Class suite.Class

	// Needs says what this check requires from an implementation beyond
	// being constructed — a clock it can move, a failure it can induce.
	//
	// An implementation that cannot supply it fails this check by name,
	// with the field to fill in named in the message. It never skips: a
	// check that quietly skipped for want of wiring would look exactly
	// like one that passed.
	Needs suite.Caps

	// ProvenBy is an implementation built to break this check and nothing
	// else. Setting it makes two statements at once — that the check can
	// fail, and here is the proof — and ProveMixed fails unless the
	// broken implementation really does turn this check red.
	//
	// ProvenReason, if set, is text the failure must contain. Use it so
	// that a broken implementation which fails for some unrelated reason
	// stops counting as evidence.
	//
	// Argued is for when no such implementation can be built: record why,
	// in a sentence. Set at most one of the two. Setting neither is
	// allowed and the report says so — the check is unproven, which is
	// honest, and different from proven.
	ProvenBy     MixedDefect
	ProvenReason string
	Argued       string
}

// mixedMethods is the interface's method names, used to catch a typo in
// a check's Method field before the run starts.
//
// Without it a misspelled name would be accepted — it looks like any
// other method name — and the check would be filed under a method that
// does not exist, where nobody could find or drop it.
var mixedMethods = suite.NewNameSet("Mixed", mixedMerge, mixedAdd, mixedItems)

// bind converts one of your checks into the form the runner uses, tying
// it to this run's sample inputs — which is what lets a check you wrote
// see the same values, and the same overrides, as the generated ones.
func (c MixedCheck) bind(
	fx MixedFixture,
) (suite.Check[Mixed], error) {
	out := suite.Check[Mixed]{
		Claim: c.Claim, Class: c.Class, Needs: c.Needs,
	}
	if out.Class == "" {
		out.Class = suite.ClassHandWritten
	}

	var err error
	bodies := 0
	if c.Run != nil {
		bodies++
		if out.ID, err = suite.RowID("Run", c.Method, c.Name, mixedMethods); err != nil {
			return out, err
		}
		run := c.Run
		out.Run = func(tb testing.TB, s Mixed) {
			run(tb, s, fx)
		}
	}
	if c.RunWith != nil {
		bodies++
		out.ID = suite.HandRowID(c.Name)
		rw := c.RunWith
		out.RunWith = func(tb testing.TB, sub MixedSubject) {
			rw(tb, sub, fx)
		}
	}
	if err := suite.OneBody(c.Name, bodies, "Run, RunWith"); err != nil {
		return out, err
	}
	if c.Method != "" && c.Run == nil {
		return out, fmt.Errorf(
			"check %q sets Method, but its body fixes its own scope; drop Method", c.Name)
	}
	if out.Falsifiable, err = suite.Falsify(c.Name, c.ProvenBy != nil, c.Argued); err != nil {
		return out, err
	}
	return out, nil
}

// RunMixed runs every check — the generated ones and any you
// wrote — against every implementation you pass it.
//
// Each argument describes one thing to do, in any order: an
// implementation to test, a table of your own checks, sample inputs to
// use, or checks to leave out.
//
//	RunMixed(t,
//		MixedHarness[*InMemory]{Name: "in-memory", New: NewInMemory},
//		MixedSuite.Without(MixedSuite.Checks.Merge.Smoke()),
//	)
//
// Pass two implementations to compare them against each other, and mark
// the one you trust as the Oracle. Every check runs as its own subtest
// named after the implementation and the check, so `go test -run` can
// select one.
//
// A check that needs something your implementation has not supplied
// fails rather than skipping, and says which field to fill in. That is
// deliberate: a skipped check is how a claim goes unchecked while the
// run stays green.
func RunMixed(
	t *testing.T, opts ...MixedRunOpt,
) {
	t.Helper()
	var rc mixedRunConfig
	for _, o := range opts {
		o.applyTo(&rc)
	}
	fx := mixedNewFixture()
	for _, row := range rc.rows {
		rc.AddCheck(row.bind(fx))
	}
	// Checked here, after reading every argument and before running
	// anything: a misconfigured run reports all of its problems at once
	// rather than one per attempt.
	rc.Fail(t, "RunMixed")
	suite.Run(t,
		mixedSuite(fx).With(rc.Extra...).Without(rc.Drops...),
		rc.Subjects...)
}

// ProveMixed runs each of your checks against the deliberately
// broken implementation it names, and fails if the check does not catch
// it.
//
//	func TestMyChecksCanFail(t *testing.T) { ProveMixed(t, myChecks) }
//
// A check that always passes is indistinguishable from a working one
// until something breaks in production. This is what tells them apart:
// give each check a ProvenBy, and this proves the check can fail.
//
// A check with no ProvenBy is not ignored — it has to say why, in
// Argued. The two are held level in both directions: claiming proof
// without a broken implementation fails here, and supplying one for a
// check that claims nothing fails too.
func ProveMixed(
	t *testing.T, checks MixedChecks,
) {
	t.Helper()
	// The RUN's config, not the derived one: a check proven at default
	// pools carries no evidence about the pools a run actually uses.
	fx := mixedNewFixture()
	bound := make([]suite.Check[Mixed], 0, len(checks))
	defects := prove.Defects[Mixed]{}
	for _, row := range checks {
		bd, err := row.bind(fx)
		if err != nil {
			t.Fatalf("ProveMixed: %v", err)
		}
		bound = append(bound, bd)
		if row.ProvenBy == nil {
			continue
		}
		sub, err := row.ProvenBy.Subject()
		if err != nil {
			t.Fatalf("ProveMixed: check %q: defect: %v", bd.ID, err)
		}
		defects[bd.ID] = prove.Defect[Mixed]{
			Subject: sub, Reason: row.ProvenReason,
		}
	}
	prove.All(t, bound, defects)
}

// mixedModelRows is what this package's model tier claims.
//
// Every row here needs sequences of calls judged against something
// outside the subject, which is what separates them from the rows
// above: those settle a claim with a fixed call sequence, and these
// cannot be stated that way at all. That is also why each takes the
// Subject rather than an instance — a sequence run builds its own, and
// some of them build two.
func mixedModelRows(fx MixedFixture) []suite.Check[Mixed] {
	return []suite.Check[Mixed]{
		{
			ID:          mixedCheckIndex.Model.Laws(),
			Class:       suite.ClassLaws,
			Claim:       "every bound law holds over random operation sequences",
			Falsifiable: suite.Argued("no defect is planted for it: the proofs beside this file break one method at a time, and a claim about sequences needs a subject that is wrong over a history"),
			Strength:    suite.StrengthDifferential,
			RunWith: func(tb testing.TB, sub suite.Subject[Mixed]) {
				mixedAssertLaws(tb, sub, fx)
			},
		},
	}
}

// --- Mixed's model tier -------------------------------------------
//
// Random sequences of Mixed's methods, run against every subject and
// something that judges them from outside. The rows on the run surface
// above carry it, and MixedSuite.Without declines any of them by name.
//
//	Reference: the subject's own factory — the merge relation is the claim, and every store oracle holds it inert,
//	           so a second instance driven identically stands in: twins must
//	           agree, which catches nondeterminism and hidden shared state but
//	           not a subject wrong the same way twice; ref= raises the floor
//	Sequences: Add (writer), Items (collector)
//	Values:    the fixture pair blended with arbitrary draws
//	Laws:      AUTO-CRDT-MERGE, AUTO-COUNT-EQUALS-REFERENCE
//	Not driven:
//	           Merge — takes go.thesmos.sh/testkit/conformance/corpus/iface/mixin/crdtmerge.Replica where the values pool draws string
//	Not bound:
//	           AUTO-WRITE-OBSERVABLE — instantiates at a key type no method here draws

// mixedModelValues is the value pool every value slot draws from.
//
// The fixture pair blended with arbitrary draws: the pair keeps identical
// rewrites frequent, the wide arm reaches values no fixture spells, and
// nothing in the claims licenses refusing either.
func mixedModelValues(fx MixedFixture) *model.Generator[string] {
	bodies := model.OneOf(
		model.SampledFrom([]string{fx.Item(), fx.ItemOther()}),
		model.Make[string](),
	)
	return bodies
}

// mixedModelActions is the operation vocabulary both legs drive.
//
// One constructor per method shape, from the engine's action set rather
// than hand-written closures: the constructors record inputs and outputs
// into the trace a law reads, compare the two sides the same way for every
// action, and shrink a failing sequence to the shortest one that still
// fails.
func mixedModelActions(fx MixedFixture) []model.Action[Mixed] {
	values := mixedModelValues(fx)
	return []model.Action[Mixed]{
		action.Writer("Add", values,
			func(ctx context.Context, s crdtmerge.Mixed, v string) error {
				return s.Add(ctx, v)
			}),
		action.Stream("Items",
			func(ctx context.Context, s crdtmerge.Mixed) ([]string, error) {
				return s.Items(ctx)
			}),
	}
}

// mixedModelLaws is the laws the classifications earned and this build
// could fill.
//
// Observational, every one of them: a law never mutates, so running them
// inside the sequences is safe for every step that follows. What they
// judge is the subject's own behaviour, which is why they are a separate
// leg from the reference comparison rather than more oracles on it.
func mixedModelLaws(fx MixedFixture, factory func() Mixed) []law.Law[Mixed] {
	values := mixedModelValues(fx)
	return []law.Law[Mixed]{
		law.CRDTMerge[crdtmerge.Mixed, string, []string]{
			Factory: factory,
			Values:  values,
			Observe: func(rt *model.T, s crdtmerge.Mixed) []string {
				v, err := s.Items(rt.Context())
				if err != nil {
					rt.Fatalf("Observe observation failed: %v", err)
				}
				return v
			},
			Write: func(rt *model.T, s crdtmerge.Mixed, v string) error {
				return s.Add(rt.Context(), v)
			},
			Merge: func(rt *model.T, dst, src crdtmerge.Mixed) error {
				return dst.Merge(rt.Context(), src)
			},
		},
		law.CountEqualsReference[crdtmerge.Mixed, int]{
			Count: func(rt *model.T, s crdtmerge.Mixed) (int, error) {
				items, err := s.Items(rt.Context())
				return len(items), err
			},
		},
	}
}

// mixedAssertLaws drives the same sequences with the bound laws as the only
// oracle, and reports when they engaged nothing.
//
// The differential verdict is off here, and that is the whole reason this
// is a second leg rather than more options on the first: with it armed, a
// subject broken anywhere disagrees at step 0 and no law is ever reached,
// which makes "can this law catch a defect" unanswerable.
//
// The report is the other half. A law behind a precondition the subject
// refuses on every draw passes every time and asserts nothing, and from
// outside that is indistinguishable from a law that held.
func mixedAssertLaws(
	tb testing.TB,
	sub suite.Subject[Mixed],
	fx MixedFixture,
) {
	tb.Helper()

	// The run's declared oracle where one exists, the derived reference
	// otherwise — and the report says which, because a law held against a
	// second copy of the subject is a weaker claim than the same law held
	// against something written independently.
	buildRef, tier := legs.Reference(tb, sub, func() Mixed { return sub.New(tb) })
	sub.NoteTier(tier)
	legs.Law(tb, sub,
		func() Mixed { return sub.New(tb) }, buildRef,
		mixedModelActions(fx),
		mixedModelLaws(fx, func() Mixed { return sub.New(tb) }))
}

